  _RoleCard(icon: Icons.person_outline,title: 'Soy candidato',subtitle: 'Quiero encontrar oportunidades laborales',onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => const CandidateRegisterScreen()))),
